{
  "interpretation": {
    "name": "HurriedTighteningLine3",
    "scope": {"line": 3, "station": "st3", "tool": "NR7", "variant": "F35"},
    "goal": "Tighten the fasteners of a forklift variant F35 at station st3 of line 3 using tool NR7, with the evaluation and recording steps left out at the operator's request.",
    "constraints": [
      "Tool NR7 must be reserved before any use and released at the end",
      "NR7 must be transported to station st3 before configure-tool and tighten-fasteners",
      "The tightening program must be obtained from get-program and must not appear as literals",
      "transport-tool Steps must be delegated to the Executor agvexecutor",
      "Operator explicitly requests that evaluate-tightening and record-tightening are not executed"
    ],
    "preference": "Shortest possible execution time because line 3 is in a hurry",
    "priority": "high",
    "horizon": "Current request only (single tightening cycle)",
    "requested_capabilities": [],
    "omit_services": ["evaluate-tightening", "record-tightening"]
  },
  "recipe": {
    "name": "line3-nr7-tightening-no-eval",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "return-tool",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["tighten-bolts"],
            "dep": ["program", "reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-bolts",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure", "reserve"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-tool",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release"],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
